-- Lessons
delete from public.lessons where key not in ('what-founders-do', 'spotting-problems', 'problems-to-opportunities', 'brainstorm-like-a-founder', 'choose-the-best-idea', 'build-a-prototype', 'who-is-your-customer', 'ask-good-questions', 'learn-from-answers', 'what-things-cost', 'setting-a-price', 'revenue-and-profit', 'why-stories-work', 'parts-of-a-pitch', 'present-with-confidence', 'what-is-an-investor', 'ownership-and-shares', 'what-investors-look-for');
update public.lessons set position = position + 100;
insert into public.lessons (module_id, key, position, title, est_minutes, body)
select m.id, v.key, v.position, v.title, v.est_minutes, v.body
from (values
  ('think-like-a-founder', 'what-founders-do', 1, 'What does a founder do?', 5, '{"intro":"A founder is someone who starts something new to make life better for other people. Let''s find out what founders actually do — and why you can start thinking like one today.","blocks":[{"type":"text","heading":"Founders start things","body":"A founder notices something that could be better and decides to do something about it. They might start a business, a club, a charity or a school project. The thing they start is often called a venture."},{"type":"example","title":"The water-bottle refill map","body":"Mia noticed that people in her town kept buying plastic bottles of water because they didn''t know where the free refill taps were. She drew a map of every tap in the park and the library and pinned it up at the sports centre. That''s founder thinking: she spotted a problem, came up with a simple fix, and tested it.","scene":"magnifier"},{"type":"list","heading":"Habits founders practise","items":["Curiosity — asking \"why does it work like this?\"","Listening — finding out what other people actually need.","Persistence — trying again when the first idea doesn''t work.","Honesty — telling the truth about what works and what doesn''t.","Teamwork — asking for help and sharing the credit."]},{"type":"keyIdea","body":"You don''t need money or to be a grown-up to think like a founder. You need curiosity and a wish to help."}],"reflect":"Think of a time you fixed something annoying, even something small. Tell your grown-up what you did.","takeaway":"A founder spots something that could be better and starts something to improve it."}'::jsonb),
  ('think-like-a-founder', 'spotting-problems', 2, 'Be a problem detective', 6, '{"intro":"Every business starts with a problem. Founders train themselves to notice problems that other people walk straight past. Time to put on your detective hat.","blocks":[{"type":"text","heading":"What counts as a problem?","body":"A problem is anything that is annoying, slow, difficult, expensive, unsafe or wasteful for someone. If people grumble about it, wait for it, or work around it, there''s probably a problem hiding there."},{"type":"steps","heading":"The detective questions","items":[{"title":"Who?","body":"Who has this problem? Be specific: \"younger kids at the bus stop\", not \"people\"."},{"title":"What?","body":"What exactly goes wrong?"},{"title":"When and how often?","body":"Does it happen every day, every week or once a year?"},{"title":"Why does it matter?","body":"What happens because of it? Lost time, money, fun or safety?"}]},{"type":"example","title":"A vague problem vs. a clear one","body":"Vague: \"Lunch is bad.\"\nClear: \"The lunch queue takes 20 minutes, so lots of students have only 10 minutes left to eat and play.\"\nThe clear version tells you who, what, how often and why it matters — so you can start thinking of fixes.","scene":"check"},{"type":"keyIdea","body":"A clear problem statement says who has the problem, what goes wrong, and why it matters."}],"reflect":"Look around your home or classroom. What is one thing people often grumble about? Who has that problem?","takeaway":"Good founders describe problems clearly: who has it, what goes wrong and why it matters."}'::jsonb),
  ('think-like-a-founder', 'problems-to-opportunities', 3, 'From problem to opportunity', 6, '{"intro":"Not every problem is worth building a business around. Founders look for opportunities: problems that lots of people have, often, and would be glad to see solved.","blocks":[{"type":"text","heading":"What is an opportunity?","body":"An opportunity is a problem you could help solve in a way people value. The bigger and more common the problem, the bigger the opportunity tends to be."},{"type":"table","caption":"Three questions to size up a problem","columns":["Question","Why it matters"],"rows":[["How many people have it?","A problem shared by many people is a bigger opportunity."],["How often does it happen?","A weekly problem matters more than a once-a-year one."],["How painful is it?","If people already spend time or money working around it, they care."]]},{"type":"example","title":"Holiday plant rescue","body":"Leo noticed that every summer his neighbours'' plants dried out while they were away. Lots of families went away, it happened every holiday, and people were sad to lose their plants. He offered a plant-watering service with his older sister — and had five families sign up in the first week.","scene":"lightbulb"},{"type":"scenario","title":"Already solved?","body":"Sometimes a problem is already solved well and for free. That doesn''t mean you should give up thinking — but it means you''d need to do something better, cheaper or different."}],"reflect":"Pick one problem you noticed. How many people have it, and how often? Is it a big opportunity or a small one?","takeaway":"An opportunity is a problem many people have, often, and want solved."}'::jsonb),
  ('create-your-idea', 'brainstorm-like-a-founder', 1, 'Brainstorm like a founder', 5, '{"intro":"Once you''ve found a problem, it''s time for ideas — lots of them. Brainstorming is a way of coming up with many ideas quickly before choosing the best one.","blocks":[{"type":"text","heading":"Start with \"How might we…?\"","body":"Turn the problem into a question that invites ideas. If the problem is \"Kids forget their water bottles\", ask \"How might we help kids remember their water bottles?\""},{"type":"list","heading":"Brainstorming rules","items":["Go for lots of ideas — quantity first, quality later.","No judging yet. Every idea gets written down.","Build on other ideas: say \"yes, and…\" instead of \"no, but…\".","Wild ideas are welcome. They often lead to clever, practical ones.","Set a timer — 5 minutes keeps the energy up."]},{"type":"example","title":"Ten ideas in five minutes","body":"Sam''s group asked \"How might we make the walk to school safer in the dark?\" Ideas included reflective stickers, a walking buddy rota, a light-up backpack, glow-in-the-dark shoelaces and a map of well-lit routes. Not all were practical, but the list gave them three ideas worth testing.","scene":"brainstorm"},{"type":"keyIdea","body":"Creativity is a skill. The more ideas you write down, the more likely one of them is great."}],"reflect":"Pick a problem from Module 1. Can you and your grown-up think of five ideas in two minutes?","takeaway":"Ask \"How might we…?\", write lots of ideas, and don''t judge them yet."}'::jsonb),
  ('create-your-idea', 'choose-the-best-idea', 2, 'Choose an idea that fits', 6, '{"intro":"You''ve got a long list of ideas. Now it''s time to be a judge. Founders check each idea against the problem to find one that really fits.","blocks":[{"type":"table","caption":"The idea check","columns":["Question","What you''re looking for"],"rows":[["Does it solve the problem?","It must fix the actual problem, not a different one."],["Would people use it?","It should be easy and appealing for the people with the problem."],["Can we make it?","Could you build a simple version with what you have?"],["Is it safe and kind?","It shouldn''t hurt anyone or anything, including the planet."]]},{"type":"example","title":"The forgotten water bottles","body":"Problem: kids forget their water bottles at home. A bottle clip on the school bag fixes it — the bottle stays with the bag. A louder school bell doesn''t fix it at all, even though it''s an idea. Always check: does this idea fix THIS problem?","scene":"check"},{"type":"text","heading":"Innovation means making something better","body":"Innovation doesn''t have to mean inventing something nobody has ever seen. Making something cheaper, simpler, safer or more fun is innovation too."}],"reflect":"Look at your five ideas. Which one best fixes the problem? Why?","takeaway":"The best idea is the one that actually fixes the problem — and that people would use."}'::jsonb),
  ('create-your-idea', 'build-a-prototype', 3, 'Build a quick prototype', 6, '{"intro":"Before spending lots of time or money, founders build a prototype: a quick, simple version of the idea that people can try.","blocks":[{"type":"text","heading":"What is a prototype?","body":"A prototype is a rough early version made to learn from. It can be a paper sketch, a cardboard model, a role-play or a pretend app drawn on paper. It doesn''t need to look perfect — it needs to help you learn."},{"type":"steps","heading":"The build–test–learn loop","items":[{"title":"Build","body":"Make the simplest version you can, quickly and cheaply."},{"title":"Test","body":"Let a few people try it. Watch what they do."},{"title":"Learn","body":"What worked? What confused them? Change the idea, then go round again."}]},{"type":"example","title":"The cardboard lunch box","body":"Aisha thought a lunch box with separate sections would stop sandwiches getting squashed. Before buying anything, she taped cardboard dividers into an old box and let three friends use it for a week. They loved the sections — but said it needed a handle. She learned that for free.","scene":"prototype"},{"type":"keyIdea","body":"Test early and cheaply. It''s much easier to change a cardboard model than a finished product."}],"reflect":"How could you build a prototype of your idea using paper, cardboard or a role-play?","takeaway":"Build a quick prototype, test it with people, learn and improve."}'::jsonb),
  ('know-your-customers', 'who-is-your-customer', 1, 'Who is your customer?', 5, '{"intro":"A business only works if someone wants what it offers. Those people are your customers. Knowing exactly who they are helps you build the right thing.","blocks":[{"type":"text","heading":"Users and buyers","body":"The user is the person who uses the product. The buyer is the person who pays. Sometimes they''re the same person — and sometimes they''re not. A toy for a 5-year-old is used by the child, but usually bought by a parent or carer."},{"type":"list","heading":"Describe your customer","items":["Who are they? (for example: students aged 10–13 who walk to school)","What problem do they have?","What do they care about? (price, speed, fun, looks, safety…)","Where could you find them to ask questions?"]},{"type":"example","title":"Not \"everyone\"","body":"When Jordan first described customers for his bike-repair stall he said \"everyone\". But everyone doesn''t ride a bike! When he changed it to \"kids in the neighbourhood with bikes that need small fixes\", he knew where to put posters and what to charge.","scene":"people"},{"type":"keyIdea","body":"\"Everyone\" is not a customer. The more specific you are, the easier it is to help them."}],"reflect":"For your idea, who would use it and who would pay for it? Are they the same person?","takeaway":"Know who uses your product and who pays — and describe them specifically."}'::jsonb),
  ('know-your-customers', 'ask-good-questions', 2, 'Ask good questions', 6, '{"intro":"Market research means finding out what customers really think and do. The secret is asking questions that get honest answers — not the answers you hope for.","blocks":[{"type":"text","heading":"Why people tell you what you want to hear","body":"If you ask \"Would you buy my amazing idea?\", most people say yes to be kind. That isn''t useful. Better questions ask about real life and what people actually did."},{"type":"table","caption":"Leading questions vs. good questions","columns":["Leading question (avoid)","Better question"],"rows":[["Don''t you hate forgetting your water bottle?","When did you last forget your water bottle? What happened?"],["Would you buy my brilliant lunch box?","How do you carry your lunch now? What''s annoying about it?"],["You''d pay 10 FB, right?","What have you spent on something like this before?"]]},{"type":"list","heading":"Research safely","items":["Ask people you know — family, friends, classmates — with a grown-up''s OK.","Never collect names, addresses or phone numbers. Tally answers instead.","Listen more than you talk."]},{"type":"keyIdea","body":"Ask about real past experiences, not about whether they like your idea."}],"reflect":"Write one good, non-leading question you could ask about your idea. Practise asking it to your grown-up.","takeaway":"Good research questions are open, fair and about real experiences."}'::jsonb),
  ('know-your-customers', 'learn-from-answers', 3, 'Learn from the answers', 6, '{"intro":"You''ve asked your questions. Now turn the answers into something you can learn from. A little maths helps you see the pattern.","blocks":[{"type":"text","heading":"Tally your answers","body":"Keep a simple tally chart: one mark for each answer. You don''t need names — just count. Then look for patterns: what did most people say?"},{"type":"example","title":"Turning a tally into a percentage","body":"Priya asked 10 classmates if they had trouble keeping their pencils sharp. 6 said yes. To find the percentage: 6 ÷ 10 = 0.6, and 0.6 × 100 = 60%. So 60% of the people she asked had the problem.","scene":"chart"},{"type":"list","heading":"What to look for","items":["How many people have the problem? (a high percentage is a good sign)","What words do people use to describe it? Use their words in your pitch.","Surprises — answers you didn''t expect are often the most useful."]},{"type":"scenario","title":"What if the answers say \"no\"?","body":"If very few people have the problem, that''s useful too. It''s much better to learn that early. You can change your idea, or look for a different group of customers."}],"reflect":"If only 2 out of 10 people had your problem, what would you do next?","takeaway":"Count answers, turn them into percentages and look for patterns."}'::jsonb),
  ('understand-business', 'what-things-cost', 1, 'What does it cost?', 6, '{"intro":"Every business spends money to make and sell things. These are its costs. In Little Founders we use pretend money called Founder Bucks (FB) — but the maths is the same as with real money.","blocks":[{"type":"text","heading":"Two kinds of cost","body":"Fixed costs stay the same however many things you sell — like a table for your stall. Variable costs go up with every item you make — like the lemons in each cup of lemonade."},{"type":"table","caption":"A lemonade stand''s costs","columns":["Cost","Type"],"rows":[["A folding table (bought once)","Fixed"],["A painted sign","Fixed"],["Lemons and sugar for each cup","Variable"],["A paper cup for each drink","Variable"]]},{"type":"example","title":"Cost per item","body":"If 10 cups of lemonade need 20 FB of lemons, sugar and cups, the variable cost per cup is 20 ÷ 10 = 2 FB. Knowing the cost of each item helps you choose a price.","scene":"costs"},{"type":"keyIdea","body":"Fixed costs don''t change with how much you sell. Variable costs grow with every item."}],"reflect":"Think of a business you''d like to run. What would you need to buy once? What would you need for every item?","takeaway":"Know your fixed costs, your variable costs and the cost of making one item."}'::jsonb),
  ('understand-business', 'setting-a-price', 2, 'Setting a price', 6, '{"intro":"Choosing a price is one of the most important decisions a founder makes. Too low and you lose money. Too high and nobody buys.","blocks":[{"type":"list","heading":"Three things to check","items":["Your cost: the price must be higher than what each item costs you to make.","Your customers: what would they be happy to pay?","Other options: what do similar things cost elsewhere?"]},{"type":"example","title":"Pricing a bookmark","body":"Each hand-made bookmark costs 3 FB in card and ribbon. Similar bookmarks at the school fair sell for 6–8 FB. A price of 7 FB covers the cost, leaves something extra, and is fair compared with others.","scene":"price-tag"},{"type":"scenario","title":"Value, not just cost","body":"Customers pay for what something does for them, not for what it cost you. A bookmark with someone''s favourite animal on it may be worth more to them than a plain one — even if both cost the same to make."},{"type":"keyIdea","body":"A good price covers your costs, feels fair to customers and makes sense next to other options."}],"reflect":"Think of something you bought recently. Do you think the price was fair? Why?","takeaway":"Price above your cost, at a level customers think is fair."}'::jsonb),
  ('understand-business', 'revenue-and-profit', 3, 'Revenue and profit', 7, '{"intro":"How do you know if a business is doing well? Two words help: revenue and profit. They sound similar but mean different things.","blocks":[{"type":"steps","heading":"The two formulas","items":[{"title":"Revenue = price × number sold","body":"All the money that comes in from sales."},{"title":"Profit = revenue − costs","body":"What''s left after you pay for everything."}]},{"type":"example","title":"A Saturday lemonade stand","body":"You sell 20 cups at 5 FB each. Revenue = 5 × 20 = 100 FB. Your lemons, sugar, cups and a sign cost 40 FB in total. Profit = 100 − 40 = 60 FB.","scene":"profit"},{"type":"text","heading":"What if profit is negative?","body":"If costs are bigger than revenue, the result is a loss. Founders then look for ways to lower costs, change the price or sell more — and try again."},{"type":"keyIdea","body":"Revenue is what comes in. Profit is what''s left after costs."}],"reflect":"If your lemonade stand made a loss, what are two things you could change?","takeaway":"Revenue = price × number sold. Profit = revenue − costs."}'::jsonb),
  ('pitch-your-idea', 'why-stories-work', 1, 'Why stories work', 5, '{"intro":"A pitch is a short talk that explains your idea and why it matters. The best pitches don''t sound like a list of facts — they tell a story.","blocks":[{"type":"text","heading":"People remember stories","body":"Our brains are built to follow stories. When you describe a real person with a real problem, listeners picture it and care about what happens next."},{"type":"steps","heading":"A simple story shape","items":[{"title":"Hook","body":"Grab attention with a question or a surprising moment."},{"title":"Problem","body":"Show who is struggling and why."},{"title":"Solution","body":"Introduce your idea as the turning point."},{"title":"Happy ending","body":"Show how life is better with your idea."}]},{"type":"example","title":"Two ways to start","body":"Flat: \"My product is a lunch box with sections.\"\nStory: \"Have you ever opened your lunch to find your sandwich squashed by an apple? That happened to me every week — until I designed a lunch box with sections.\"","scene":"story"},{"type":"keyIdea","body":"Start with a hook, show the problem, then reveal your solution."}],"reflect":"Think of a hook question for your idea that starts with \"Have you ever…?\" Try it on your grown-up.","takeaway":"Good pitches are stories: hook, problem, solution, happy ending."}'::jsonb),
  ('pitch-your-idea', 'parts-of-a-pitch', 2, 'The parts of a pitch', 6, '{"intro":"Every strong pitch answers the same few questions. If one is missing, listeners are left wondering.","blocks":[{"type":"table","caption":"Five questions every pitch answers","columns":["Part","Question it answers"],"rows":[["Problem","What''s wrong, and who has it?"],["Solution","What is your idea and how does it fix the problem?"],["Customer","Who exactly will use it or buy it?"],["Business","How does it make money, and what does it cost?"],["Next step","What do you want to do next, or what help do you need?"]]},{"type":"example","title":"A 30-second pitch","body":"\"Every summer, plants die while families are on holiday (problem). Plant Pals waters them for you (solution). We help families on our street who travel in the summer (customer). We charge 5 FB a visit and our costs are about 1 FB (business). Next, we want to test it with ten families (next step).\"","scene":"pitch"},{"type":"keyIdea","body":"Problem, solution, customer, business, next step — check your pitch has all five."}],"reflect":"Can you say all five parts of your pitch in 30 seconds? Time yourself with your grown-up.","takeaway":"A complete pitch covers problem, solution, customer, business and next step."}'::jsonb),
  ('pitch-your-idea', 'present-with-confidence', 3, 'Present with confidence', 6, '{"intro":"Feeling nervous before presenting is normal — even for experienced founders. Practice and a few simple habits make a big difference.","blocks":[{"type":"list","heading":"Confident presenting habits","items":["Practise out loud a few times, ideally to a friendly audience.","Look at your listeners, not at the floor.","Speak slowly and pause after important points.","Stand still and smile — it helps you and your audience relax.","Keep it short. You can always add detail when people ask."]},{"type":"text","heading":"Handling questions","body":"Questions mean people are interested! Listen to the whole question, take a breath, then answer honestly. If you don''t know, say so: \"Great question — I don''t know yet, but I''ll find out.\" That''s much better than guessing."},{"type":"example","title":"Turning nerves into energy","body":"Before her school pitch, Zara practised three times in front of her family and wrote her five parts on a small card. When a judge asked a question she couldn''t answer, she said she''d test it next week. The judges said that honesty was one of the best parts of her pitch.","scene":"stage"},{"type":"keyIdea","body":"Practise, slow down, look at your audience — and be honest when you don''t know."}],"reflect":"Practise your 30-second pitch twice for your grown-up. Ask them to tell you one thing you did well.","takeaway":"Practise, speak slowly and answer questions honestly."}'::jsonb),
  ('meet-the-investors', 'what-is-an-investor', 1, 'What is an investor?', 6, '{"intro":"Some businesses need more money than the founders have to grow. One way to get it is from investors. Let''s find out who they are and what they want. (In Little Founders everything is pretend — no real money is ever involved.)","blocks":[{"type":"text","heading":"Investors buy a piece of the business","body":"An investor gives money to a business, hoping it will grow. In return, they usually get a share — a piece of the business. If the business grows, their piece becomes worth more. If it fails, they can lose their money. That''s called risk."},{"type":"table","caption":"Ways a business can get money","columns":["Way","What it means"],"rows":[["Savings and sales","Using money the business already earned — you keep full control."],["Loan","Borrowing money you must pay back, often with extra (interest)."],["Grant or prize","Money given for a purpose, usually not paid back."],["Investment","Money in exchange for a share of the business."]]},{"type":"example","title":"The bakery that grew","body":"A small bakery wanted a bigger oven to bake more bread. An investor gave them the money in exchange for a share of the bakery. The bakery sold more, and the investor''s share became more valuable. Both were happy — but they took the risk that it might not work.","scene":"investor"},{"type":"keyIdea","body":"Investors give money in exchange for a share of the business — and they take a risk."}],"reflect":"If you had a business, would you rather use your own savings, borrow or find an investor? Talk about why with your grown-up.","takeaway":"An investor gives money for a share of the business and takes a risk."}'::jsonb),
  ('meet-the-investors', 'ownership-and-shares', 2, 'Ownership and shares', 7, '{"intro":"When an investor gets a share of a business, who owns what? Picture the business as a pizza cut into slices.","blocks":[{"type":"text","heading":"The business pizza","body":"Imagine your business is one pizza cut into 10 equal slices. At the start you own all 10 slices — 100% of the business. Each slice is 10%."},{"type":"example","title":"Sharing slices","body":"An investor offers pretend money in exchange for 3 slices. Now the investor owns 3 slices (30%) and you own 7 slices (70%). You still own most of the business, but you share it — and you might share some decisions too.","scene":"pie"},{"type":"list","heading":"Things to think about before sharing","items":["How much of your business are you giving away?","What will you do with the money? Will it help the business grow?","Will the investor help with advice, or only money?","Will you still own enough to make the big decisions?"]},{"type":"keyIdea","body":"Shares are slices of ownership. Giving some away means owning less — so it should help the business grow."}],"reflect":"Would you rather own all of a small pizza or most of a much bigger one? Why?","takeaway":"Each share is a slice of ownership. Know how much you keep."}'::jsonb),
  ('meet-the-investors', 'what-investors-look-for', 3, 'What investors look for', 6, '{"intro":"Investors hear lots of pitches. They ask questions to decide which businesses are likely to grow. Knowing what they look for helps you prepare.","blocks":[{"type":"list","heading":"Signs investors like","items":["A real problem that many people have.","Evidence: customers who''ve tried it and want more.","A founder who knows their costs, prices and profit.","A team that listens, learns and keeps improving.","Honesty about what''s working and what isn''t."]},{"type":"table","caption":"Questions investors often ask","columns":["Question","What they want to know"],"rows":[["Who are your customers?","That you know exactly who you''re helping."],["How do you make money?","That the business can earn more than it spends."],["What will you use the money for?","That the investment will help you grow."],["What''s the biggest risk?","That you''re honest and have thought ahead."]]},{"type":"keyIdea","body":"Investors look for a real problem, evidence, honest founders and a clear plan."}],"reflect":"What''s the biggest risk for your idea? How might you reduce it?","takeaway":"Show investors evidence, know your numbers and be honest about risks."}'::jsonb)
) as v(module_key, key, position, title, est_minutes, body)
join public.modules m on m.key = v.module_key
on conflict (key) do update
  set module_id = excluded.module_id, position = excluded.position, title = excluded.title,
      est_minutes = excluded.est_minutes, body = excluded.body;

-- Lesson activities (answer keys are hidden from clients by column grants)
delete from public.lesson_activities where key not in ('what-founders-do-activity', 'spotting-problems-activity', 'problems-to-opportunities-activity', 'brainstorm-like-a-founder-activity', 'choose-the-best-idea-activity', 'build-a-prototype-activity', 'who-is-your-customer-activity', 'ask-good-questions-activity', 'learn-from-answers-activity', 'what-things-cost-activity', 'setting-a-price-activity', 'revenue-and-profit-activity', 'why-stories-work-activity', 'parts-of-a-pitch-activity', 'present-with-confidence-activity', 'what-is-an-investor-activity', 'ownership-and-shares-activity', 'what-investors-look-for-activity');
insert into public.lesson_activities (lesson_id, key, kind, config, answer_key)
select l.id, v.key, v.kind, v.config, v.answer_key
from (values
  ('what-founders-do', 'what-founders-do-activity', 'choose', '{"prompt":"Which of these are founder habits? Pick all that apply.","multi":true,"options":["Asking \"why?\" when something is annoying","Giving up after the first try","Listening to what other people need","Hiding mistakes so nobody finds out"]}'::jsonb, '{"correct":[0,2],"feedback":["Yes! Curiosity is where most ideas start.","Founders usually have to try several times. Persistence is a key habit.","Exactly. Good ideas solve real needs, so founders listen a lot.","Founders are honest about mistakes so they can learn and fix them."],"explanation":"Curiosity and listening are founder habits. Giving up early and hiding mistakes get in the way of learning."}'::jsonb),
  ('spotting-problems', 'spotting-problems-activity', 'sort', '{"prompt":"Sort each statement: is it a clear problem, or too vague to work on?","buckets":["Clear problem","Too vague"],"items":["My little brother can''t reach the light switch, so he needs help every night.","Things are bad.","Football boots get muddy and make the car dirty after every Saturday match.","People are annoying."]}'::jsonb, '{"placements":[0,1,0,1],"hint":"A clear problem says who has it and what goes wrong. Look for the statements that answer those questions.","explanation":"The clear problems name who is affected and what goes wrong. \"Things are bad\" and \"people are annoying\" don''t tell you what to fix."}'::jsonb),
  ('problems-to-opportunities', 'problems-to-opportunities-activity', 'choose', '{"prompt":"Which problem is the best opportunity to build something?","multi":false,"options":["A problem only you have, once a year","A problem many families on your street have every week","A problem that''s already solved perfectly, for free"]}'::jsonb, '{"correct":[1],"feedback":["It''s real, but few people have it and it rarely happens, so it''s a small opportunity.","Yes! Lots of people, often — that''s a strong opportunity.","People already have a great free fix, so a new idea would struggle."],"explanation":"Opportunities are biggest when many people have a problem often and care about solving it."}'::jsonb),
  ('brainstorm-like-a-founder', 'brainstorm-like-a-founder-activity', 'choose', '{"prompt":"Which of these are good brainstorming rules? Pick all that apply.","multi":true,"options":["Write down every idea, even wild ones","Say \"that won''t work\" as soon as you hear an idea","Build on other people''s ideas with \"yes, and…\"","Stop after the first idea"]}'::jsonb, '{"correct":[0,2],"feedback":["Yes — wild ideas often spark practical ones.","Judging too early stops ideas flowing. Save it for later.","Great — building on ideas makes them better.","The first idea is rarely the best. Aim for lots."],"explanation":"Good brainstorming means many ideas, no early judging, and building on each other''s ideas."}'::jsonb),
  ('choose-the-best-idea', 'choose-the-best-idea-activity', 'sort', '{"prompt":"Problem: kids forget their water bottles at home. Which ideas solve this problem?","buckets":["Solves the problem","Doesn''t solve it"],"items":["A clip that keeps the bottle attached to the school bag","A sticker that says \"Have fun!\"","A reminder tag hung on the front door","A louder school bell"]}'::jsonb, '{"placements":[0,1,0,1],"hint":"Ask of each idea: would it help someone remember or keep their bottle?","explanation":"The clip and the door tag help kids remember their bottles. A sticker and a louder bell don''t change whether the bottle gets packed."}'::jsonb),
  ('build-a-prototype', 'build-a-prototype-activity', 'choose', '{"prompt":"You have an idea for a new kind of pencil case. What''s the best first step?","multi":false,"options":["Spend all your savings making 100 of them","Make a cardboard model and let three friends try it","Keep it secret until it''s perfect"]}'::jsonb, '{"correct":[1],"feedback":["That''s risky — you don''t know yet if people like it.","Yes! Quick, cheap, and you learn from real people.","Without testing, you can''t find out what to improve."],"explanation":"A cheap prototype tested with real people teaches you the most with the least risk."}'::jsonb),
  ('who-is-your-customer', 'who-is-your-customer-activity', 'choose', '{"prompt":"A business sells bath toys for toddlers. Who is usually the buyer?","multi":false,"options":["The toddler","A parent or carer","The toy factory"]}'::jsonb, '{"correct":[1],"feedback":["The toddler uses the toy, but toddlers don''t usually buy things.","Right — the toddler is the user, the grown-up is the buyer.","The factory makes the toy; it isn''t the customer."],"explanation":"The user (toddler) and the buyer (parent or carer) are different people. A good business thinks about both."}'::jsonb),
  ('ask-good-questions', 'ask-good-questions-activity', 'sort', '{"prompt":"Sort the questions: which are good research questions, and which are leading?","buckets":["Good question","Leading question"],"items":["Tell me about the last time your bike had a flat tyre.","My bike-repair stall is great, isn''t it?","How do you get your bike fixed at the moment?","You''d definitely use my stall, right?"]}'::jsonb, '{"placements":[0,1,0,1],"hint":"Leading questions push people towards a \"yes\". Good questions ask about what really happened.","explanation":"Good questions ask about real experiences. Leading questions suggest the answer you want."}'::jsonb),
  ('learn-from-answers', 'learn-from-answers-activity', 'fill', '{"prompt":"You asked 20 people. 15 said they have the problem. What percentage of people have the problem?","prefix":null,"suffix":"%"}'::jsonb, '{"answer":75,"hint":"Divide the number who said yes by the total, then multiply by 100.","explanation":"15 ÷ 20 = 0.75, and 0.75 × 100 = 75%. Three out of four people have the problem — a good sign!"}'::jsonb),
  ('what-things-cost', 'what-things-cost-activity', 'sort', '{"prompt":"A friendship-bracelet business: sort each cost as fixed or variable.","buckets":["Fixed cost","Variable cost"],"items":["A storage box for supplies (bought once)","Beads for each bracelet","A sign for the stall","Thread for each bracelet"]}'::jsonb, '{"placements":[0,1,0,1],"hint":"Ask: would this cost go up if I made one more bracelet?","explanation":"The box and sign are bought once (fixed). Beads and thread are needed for every bracelet (variable)."}'::jsonb),
  ('setting-a-price', 'setting-a-price-activity', 'choose', '{"prompt":"Each bookmark costs 3 FB to make. Similar ones sell for 6–8 FB. What''s the best price?","multi":false,"options":["1 FB","7 FB","50 FB"]}'::jsonb, '{"correct":[1],"feedback":["That''s less than it costs to make — you''d lose 2 FB on every bookmark.","Yes — it covers the cost and is fair compared with others.","Much higher than similar bookmarks, so customers would likely go elsewhere."],"explanation":"7 FB is above the 3 FB cost and in line with what customers already pay for similar bookmarks."}'::jsonb),
  ('revenue-and-profit', 'revenue-and-profit-activity', 'fill', '{"prompt":"You sell 12 bracelets at 6 FB each. Your total costs were 30 FB. What is your profit?","prefix":null,"suffix":"FB"}'::jsonb, '{"answer":42,"hint":"First find revenue (price × number sold), then subtract the costs.","explanation":"Revenue = 6 × 12 = 72 FB. Profit = 72 − 30 = 42 FB."}'::jsonb),
  ('why-stories-work', 'why-stories-work-activity', 'choose', '{"prompt":"Which is the best opening hook for a pitch about a squash-proof lunch box?","multi":false,"options":["\"Hello. This is my lunch box. Thank you.\"","\"Have you ever opened your lunch to find a squashed sandwich?\"","\"My lunch box is 22 centimetres long and 9 centimetres high.\""]}'::jsonb, '{"correct":[1],"feedback":["It''s polite, but it doesn''t grab attention or show a problem.","Yes! It''s a question everyone can picture.","Facts can come later. Start with something people care about."],"explanation":"A relatable question makes listeners picture the problem straight away."}'::jsonb),
  ('parts-of-a-pitch', 'parts-of-a-pitch-activity', 'choose', '{"prompt":"Read this pitch: \"Bikes get flat tyres (problem). I fix them quickly at my stall (solution). I charge 3 FB and parts cost 1 FB (business). Next, I''ll put up posters (next step).\" Which part is missing?","multi":false,"options":["The problem","The customer","The next step"]}'::jsonb, '{"correct":[1],"feedback":["The problem is there: bikes get flat tyres.","Yes — the pitch never says who the stall is for.","The next step is there: putting up posters."],"explanation":"The pitch doesn''t say who the customers are — for example, kids in the neighbourhood with bikes."}'::jsonb),
  ('present-with-confidence', 'present-with-confidence-activity', 'choose', '{"prompt":"Which of these are good presenting habits? Pick all that apply.","multi":true,"options":["Practising out loud before the real thing","Speaking as fast as possible to finish quickly","Saying \"I don''t know yet, but I''ll find out\" when unsure","Making up an answer so you look clever"]}'::jsonb, '{"correct":[0,2],"feedback":["Yes — practice builds confidence.","Slow down — people need time to follow.","Honest answers build trust.","Guessing can mislead people. Honesty is better."],"explanation":"Practising and answering honestly are good habits. Rushing and making things up hurt your pitch."}'::jsonb),
  ('what-is-an-investor', 'what-is-an-investor-activity', 'choose', '{"prompt":"What does an investor usually get in return for their money?","multi":false,"options":["A share (piece) of the business","Nothing — it''s a gift","Free products forever"]}'::jsonb, '{"correct":[0],"feedback":["Yes — they become part-owners.","A gift or grant isn''t an investment. Investors expect a share.","Not usually — investors want a share of the business."],"explanation":"Investors swap money for a share of the business, hoping it grows in value."}'::jsonb),
  ('ownership-and-shares', 'ownership-and-shares-activity', 'fill', '{"prompt":"Your business is split into 10 equal slices. You give 2 slices to an investor. What percentage of the business do you still own?","prefix":null,"suffix":"%"}'::jsonb, '{"answer":80,"hint":"Each slice is 10%. How many slices do you have left?","explanation":"You keep 8 of 10 slices. Each slice is 10%, so 8 × 10 = 80%."}'::jsonb),
  ('what-investors-look-for', 'what-investors-look-for-activity', 'sort', '{"prompt":"Sort these into good signs and warning signs for an investor.","buckets":["Good sign","Warning sign"],"items":["Customers tried it and asked for more","The founder doesn''t know what each item costs","The team keeps testing and improving","The founder exaggerates how many they''ve sold"]}'::jsonb, '{"placements":[0,1,0,1],"hint":"Investors want evidence and honesty. Which statements show those?","explanation":"Customer demand and continuous improvement are good signs. Not knowing costs and exaggerating are warning signs."}'::jsonb)
) as v(lesson_key, key, kind, config, answer_key)
join public.lessons l on l.key = v.lesson_key
on conflict (key) do update
  set lesson_id = excluded.lesson_id, kind = excluded.kind, config = excluded.config, answer_key = excluded.answer_key;

-- Quizzes
insert into public.quizzes (module_id, pass_mark)
select m.id, v.pass_mark
from (values
  ('think-like-a-founder', 60),
  ('create-your-idea', 60),
  ('know-your-customers', 60),
  ('understand-business', 60),
  ('pitch-your-idea', 60),
  ('meet-the-investors', 60)
) as v(module_key, pass_mark)
join public.modules m on m.key = v.module_key
on conflict (module_id) do update set pass_mark = excluded.pass_mark;

delete from public.quiz_questions where key is null or key not in ('m1-q1', 'm1-q2', 'm1-q3', 'm1-q4', 'm1-q5', 'm2-q1', 'm2-q2', 'm2-q3', 'm2-q4', 'm2-q5', 'm3-q1', 'm3-q2', 'm3-q3', 'm3-q4', 'm3-q5', 'm4-q1', 'm4-q2', 'm4-q3', 'm4-q4', 'm4-q5', 'm5-q1', 'm5-q2', 'm5-q3', 'm5-q4', 'm5-q5', 'm6-q1', 'm6-q2', 'm6-q3', 'm6-q4', 'm6-q5');
update public.quiz_questions set position = position + 100;
insert into public.quiz_questions (quiz_id, key, position, kind, prompt, explanation)
select q.id, v.key, v.position, 'single', v.prompt, v.explanation
from (values
  ('think-like-a-founder', 'm1-q1', 1, 'What is a founder?', 'A founder starts something new — a business, club or project — to solve a problem.'),
  ('think-like-a-founder', 'm1-q2', 2, 'Which of these is the clearest problem statement?', 'Clear problem statements say who has the problem, what goes wrong and why it matters.'),
  ('think-like-a-founder', 'm1-q3', 3, 'Which habit helps a founder most when their first idea doesn''t work?', 'Most first ideas need changes. Persistence means trying again with what you learned.'),
  ('think-like-a-founder', 'm1-q4', 4, 'Which makes a problem a bigger opportunity?', 'The more people have a problem, the more often, and the more they care, the bigger the opportunity.'),
  ('think-like-a-founder', 'm1-q5', 5, 'Mia drew a map of free water-refill taps. What problem was she solving?', 'People bought plastic bottles because they couldn''t find the free taps. The map solved that.'),
  ('create-your-idea', 'm2-q1', 1, 'What is the main goal of brainstorming?', 'Brainstorming is about generating many ideas without judging them, then choosing later.'),
  ('create-your-idea', 'm2-q2', 2, 'Which is a good "How might we…?" question for the problem "Plants die while families are on holiday"?', 'A good "How might we…?" question restates the problem as a challenge to solve.'),
  ('create-your-idea', 'm2-q3', 3, 'What is a prototype?', 'Prototypes are quick, rough versions you build to learn what works.'),
  ('create-your-idea', 'm2-q4', 4, 'After testing a prototype, what should you do next?', 'Build, test, learn — then improve and test again.'),
  ('create-your-idea', 'm2-q5', 5, 'Which of these counts as innovation?', 'Innovation means making something new or better — simpler, cheaper, safer or more fun.'),
  ('know-your-customers', 'm3-q1', 1, 'A bike helmet for kids is usually bought by…', 'The user (child) and buyer (grown-up) can be different people.'),
  ('know-your-customers', 'm3-q2', 2, 'Which is the best research question?', 'Good questions ask about real past experiences without suggesting the answer.'),
  ('know-your-customers', 'm3-q3', 3, 'You asked 10 people and 4 had the problem. What percentage is that?', '4 ÷ 10 = 0.4, and 0.4 × 100 = 40%.'),
  ('know-your-customers', 'm3-q4', 4, 'Why is "everyone" a weak customer description?', 'Specific customers help you design the product, set the price and find people to ask.'),
  ('know-your-customers', 'm3-q5', 5, 'What should you avoid collecting when you do research?', 'You can learn everything you need by counting answers. Personal details should stay private.'),
  ('understand-business', 'm4-q1', 1, 'Which of these is a variable cost for a cupcake stall?', 'Variable costs grow with each item you make.'),
  ('understand-business', 'm4-q2', 2, 'You sell 10 cards at 4 FB each. What is your revenue?', 'Revenue = price × number sold = 4 × 10 = 40 FB.'),
  ('understand-business', 'm4-q3', 3, 'Revenue is 50 FB and costs are 20 FB. What is the profit?', 'Profit = revenue − costs = 50 − 20 = 30 FB.'),
  ('understand-business', 'm4-q4', 4, 'A keyring costs 5 FB to make. Which price would lose money on every sale?', 'Any price below the cost of making the item loses money.'),
  ('understand-business', 'm4-q5', 5, 'What are Founder Bucks (FB)?', 'Founder Bucks are a pretend currency so you can practise business maths safely.'),
  ('pitch-your-idea', 'm5-q1', 1, 'What is a pitch?', 'A pitch is a short, clear presentation of your idea.'),
  ('pitch-your-idea', 'm5-q2', 2, 'What should come first in a story-style pitch?', 'Hook first, then the problem, then your solution.'),
  ('pitch-your-idea', 'm5-q3', 3, 'Which part of a pitch answers "Who will use or buy it?"', 'The customer part says exactly who the idea is for.'),
  ('pitch-your-idea', 'm5-q4', 4, 'A judge asks a question you can''t answer. What''s the best response?', 'Honesty builds trust, and it shows you''re still learning.'),
  ('pitch-your-idea', 'm5-q5', 5, 'Which habit helps you present confidently?', 'Practice, eye contact and a steady pace make presenting easier.'),
  ('meet-the-investors', 'm6-q1', 1, 'What is an investor?', 'Investors swap money for part-ownership of the business.'),
  ('meet-the-investors', 'm6-q2', 2, 'A business has 10 equal shares. An investor gets 4. What percentage does the investor own?', '4 out of 10 shares is 40% of the business.'),
  ('meet-the-investors', 'm6-q3', 3, 'What is "risk" for an investor?', 'Investing is risky: if the business doesn''t succeed, the investment can be lost.'),
  ('meet-the-investors', 'm6-q4', 4, 'Which is a good sign for an investor?', 'Evidence from real customers shows the idea solves a real problem.'),
  ('meet-the-investors', 'm6-q5', 5, 'In Little Founders, what kind of money do investors use?', 'All investing in Little Founders is pretend so you can learn safely.')
) as v(module_key, key, position, prompt, explanation)
join public.modules m on m.key = v.module_key
join public.quizzes q on q.module_id = m.id
on conflict (key) do update
  set quiz_id = excluded.quiz_id, position = excluded.position, prompt = excluded.prompt,
      explanation = excluded.explanation;

