insert into public.quiz_options (question_id, position, label, is_correct, feedback)
select q.id, v.position, v.label, v.is_correct, v.feedback
from (values
  ('m1-q1', 1, 'Someone who starts something new to make things better', true, 'That''s it.'),
  ('m1-q1', 2, 'Someone who works in a shop', false, 'Shop workers are important, but a founder is the person who starts something.'),
  ('m1-q1', 3, 'Someone who only gives money to businesses', false, 'That''s closer to an investor.'),
  ('m1-q2', 1, 'School is boring.', false, 'This is too vague — who, what and why aren''t clear.'),
  ('m1-q2', 2, 'Younger students wait 15 minutes in the rain for the bus because the shelter is too small.', true, 'Clear: it says who, what and why it matters.'),
  ('m1-q2', 3, 'Buses are bad.', false, 'Too vague to act on.'),
  ('m1-q3', 1, 'Hiding the result', false, 'Hiding results stops you learning from them.'),
  ('m1-q3', 2, 'Blaming customers', false, 'Customers'' reactions are useful information, not something to blame.'),
  ('m1-q3', 3, 'Persistence', true, 'Right — founders keep trying and improving.'),
  ('m1-q4', 1, 'Lots of people have it often', true, 'Yes — common, frequent problems are bigger opportunities.'),
  ('m1-q4', 2, 'Only one person has it', false, 'Fewer people means a smaller opportunity.'),
  ('m1-q4', 3, 'Nobody minds it', false, 'If nobody minds, nobody will want a fix.'),
  ('m1-q5', 1, 'The park had too many trees', false, 'That wasn''t the problem Mia noticed.'),
  ('m1-q5', 2, 'Taps were too expensive to build', false, 'The taps already existed — people just couldn''t find them.'),
  ('m1-q5', 3, 'People didn''t know where to refill bottles for free', true, 'Exactly.'),
  ('m2-q1', 1, 'To come up with lots of ideas quickly', true, 'Yes — quantity first, choose later.'),
  ('m2-q1', 2, 'To decide who is the smartest', false, 'Brainstorming is a team activity, not a competition.'),
  ('m2-q1', 3, 'To find one perfect idea straight away', false, 'The best ideas usually come after many others.'),
  ('m2-q2', 1, 'How might we make holidays longer?', false, 'That''s a different problem.'),
  ('m2-q2', 2, 'How might we keep plants watered while families are away?', true, 'That turns the problem into an invitation for ideas.'),
  ('m2-q2', 3, 'Why do people have plants?', false, 'Interesting, but it doesn''t invite solutions to the problem.'),
  ('m2-q3', 1, 'A simple early version of an idea used for testing', true, 'Exactly.'),
  ('m2-q3', 2, 'A type of advert', false, 'Prototypes are for learning, not advertising.'),
  ('m2-q3', 3, 'The final product sold in shops', false, 'A prototype comes long before the final product.'),
  ('m2-q4', 1, 'Throw away every idea', false, 'Usually you improve the idea rather than starting over.'),
  ('m2-q4', 2, 'Learn from what happened and improve the idea', true, 'Yes — that''s the build–test–learn loop.'),
  ('m2-q4', 3, 'Ignore feedback and keep going', false, 'Feedback is the whole point of testing.'),
  ('m2-q5', 1, 'Only inventions nobody has ever seen', false, 'Innovation also includes improving things that exist.'),
  ('m2-q5', 2, 'Copying someone''s product exactly', false, 'Copying isn''t innovation — and can be unfair.'),
  ('m2-q5', 3, 'Making an existing product simpler and cheaper', true, 'Yes — improving something is innovation too.'),
  ('m3-q1', 1, 'The bike shop', false, 'The shop sells it; it isn''t the customer.'),
  ('m3-q1', 2, 'Nobody', false, 'Someone has to buy it for the business to work.'),
  ('m3-q1', 3, 'A parent or carer', true, 'Yes — the child uses it, the grown-up usually buys it.'),
  ('m3-q2', 1, 'Tell me about the last time you lost your keys.', true, 'Open and about real experience. Great.'),
  ('m3-q2', 2, 'Would you pay a lot for my amazing key finder?', false, 'Leading and hypothetical.'),
  ('m3-q2', 3, 'You love my idea, don''t you?', false, 'That''s leading — people will just say yes.'),
  ('m3-q3', 1, '14%', false, 'Try 4 ÷ 10, then × 100.'),
  ('m3-q3', 2, '4%', false, 'Remember to divide by the total and multiply by 100.'),
  ('m3-q3', 3, '40%', true, 'Correct: 4 ÷ 10 × 100 = 40%.'),
  ('m3-q4', 1, 'It isn''t weak — it''s the best answer', false, 'A specific customer is much more useful.'),
  ('m3-q4', 2, 'It''s too broad to know who to help or where to find them', true, 'Exactly.'),
  ('m3-q4', 3, 'Because businesses only need one customer', false, 'Businesses usually need many customers.'),
  ('m3-q5', 1, 'Interesting words people use', false, 'Those are useful — you can use them in your pitch.'),
  ('m3-q5', 2, 'Tally marks', false, 'Tallies are a great, safe way to count answers.'),
  ('m3-q5', 3, 'People''s names, addresses or phone numbers', true, 'Right — you don''t need personal details to learn.'),
  ('m4-q1', 1, 'Flour and icing for each cupcake', true, 'Yes — you need more for every cupcake.'),
  ('m4-q1', 2, 'A tablecloth', false, 'That''s fixed too.'),
  ('m4-q1', 3, 'A cake stand bought once', false, 'That''s a fixed cost — it doesn''t change with sales.'),
  ('m4-q2', 1, '6 FB', false, 'Multiply the price by the number sold.'),
  ('m4-q2', 2, '40 FB', true, 'Correct: 4 × 10 = 40 FB.'),
  ('m4-q2', 3, '14 FB', false, 'Revenue is price × number sold, not price + number.'),
  ('m4-q3', 1, '70 FB', false, 'Profit takes costs away — it doesn''t add them.'),
  ('m4-q3', 2, '20 FB', false, 'That''s the cost. Subtract it from the revenue.'),
  ('m4-q3', 3, '30 FB', true, 'Correct: 50 − 20 = 30 FB.'),
  ('m4-q4', 1, '10 FB', false, '10 FB is above the cost.'),
  ('m4-q4', 2, '8 FB', false, '8 FB is above the cost, so it makes a profit.'),
  ('m4-q4', 3, '4 FB', true, 'Right — you''d lose 1 FB on each keyring.'),
  ('m4-q5', 1, 'A type of bank account', false, 'No — Founder Bucks are only for learning.'),
  ('m4-q5', 2, 'Pretend money used for learning in Little Founders', true, 'Yes — they can''t be spent or swapped for real money.'),
  ('m4-q5', 3, 'Real money you can spend in shops', false, 'No — Founder Bucks are pretend.'),
  ('m5-q1', 1, 'A football field', false, 'That''s a different kind of pitch!'),
  ('m5-q1', 2, 'A short talk explaining your idea and why it matters', true, 'Exactly.'),
  ('m5-q1', 3, 'A long report about everything you know', false, 'Pitches are short and focused.'),
  ('m5-q2', 1, 'A long list of prices', false, 'Prices come later.'),
  ('m5-q2', 2, 'A hook that grabs attention', true, 'Yes — start by making people care.'),
  ('m5-q2', 3, 'Thanking everyone for listening', false, 'Thank them at the end.'),
  ('m5-q3', 1, 'The hook', false, 'The hook grabs attention.'),
  ('m5-q3', 2, 'The solution', false, 'The solution explains what the idea is.'),
  ('m5-q3', 3, 'The customer', true, 'Right.'),
  ('m5-q4', 1, 'Ignore the question', false, 'Ignoring questions loses trust.'),
  ('m5-q4', 2, '"Great question — I don''t know yet, but I''ll find out."', true, 'Honest and confident.'),
  ('m5-q4', 3, 'Make up an answer', false, 'Guessing can mislead people.'),
  ('m5-q5', 1, 'Practising out loud beforehand', true, 'Yes — practice is the best cure for nerves.'),
  ('m5-q5', 2, 'Looking at the floor the whole time', false, 'Looking at your audience helps them connect with you.'),
  ('m5-q5', 3, 'Speaking as fast as you can', false, 'Slow down so people can follow.'),
  ('m6-q1', 1, 'Someone who gives money to a business in exchange for a share', true, 'Exactly.'),
  ('m6-q1', 2, 'Someone who lends money that must be paid back with interest', false, 'That''s a lender.'),
  ('m6-q1', 3, 'Someone who buys one product', false, 'That''s a customer.'),
  ('m6-q2', 1, '60%', false, 'That''s what the founder keeps.'),
  ('m6-q2', 2, '4%', false, 'Each share is 10%, not 1%.'),
  ('m6-q2', 3, '40%', true, 'Correct: 4 × 10% = 40%.'),
  ('m6-q3', 1, 'A guarantee they''ll get rich', false, 'There are no guarantees in investing.'),
  ('m6-q3', 2, 'A type of share', false, 'Risk is about the chance of losing money.'),
  ('m6-q3', 3, 'The chance they could lose their money if the business fails', true, 'Right.'),
  ('m6-q4', 1, 'The founder has no idea what things cost', false, 'Not knowing costs is a warning sign.'),
  ('m6-q4', 2, 'The founder exaggerates sales', false, 'Exaggerating breaks trust.'),
  ('m6-q4', 3, 'Customers have tried the product and want more', true, 'Yes — that''s real evidence.'),
  ('m6-q5', 1, 'Cryptocurrency', false, 'No — investing here is pretend and for learning only.'),
  ('m6-q5', 2, 'Real money from your family', false, 'No — nothing in Little Founders uses real money.'),
  ('m6-q5', 3, 'Pretend Founder Bucks — no real money', true, 'Correct. Everything here is practice.')
) as v(question_key, position, label, is_correct, feedback)
join public.quiz_questions q on q.key = v.question_key
on conflict (question_id, position) do update
  set label = excluded.label, is_correct = excluded.is_correct, feedback = excluded.feedback;

